// Edit only this object. No passwords here.
const c={"dryRun": true, "autoPublish": false, "chatId": "REPLACE_WITH_CHAT_ID", "model": "openai/gpt-oss-20b", "lookbackHours": 36, "maxPerSource": 20, "maxArticlesPerRun": 15, "minScore": 4, "minConfidence": 0.75, "waitSeconds": 70, "promptVersion": "market-fa-v2.4", "minHealthyFeeds": 2};
if(typeof c.dryRun!=='boolean'||typeof c.autoPublish!=='boolean')throw new Error('dryRun and autoPublish must be booleans');
for(const [k,min,max] of [['maxArticlesPerRun',1,30],['maxPerSource',1,20],['lookbackHours',1,72],['minScore',1,5],['waitSeconds',60,300],['minHealthyFeeds',1,8]]){
 if(!Number.isInteger(c[k])||c[k]<min||c[k]>max)throw new Error('Config out of bounds: '+k);
}
if(typeof c.minConfidence!=='number'||!Number.isFinite(c.minConfidence)||c.minConfidence<0||c.minConfidence>1)throw new Error('Invalid minConfidence');
if(!c.dryRun&&c.autoPublish&&(!c.chatId||c.chatId.includes('REPLACE_')))throw new Error('Set a private test chatId before publishing');
return [{json:c}];

const cfg=$('Config').first().json;
const sources=[["Fed Monetary", "macro"], ["ECB Press", "macro"], ["Northern Miner Gold", "gold"], ["Northern Miner Silver", "silver"], ["Cointelegraph", "crypto"], ["FXStreet", "forex"], ["BBC World", "geopolitics"], ["Al Jazeera", "geopolitics"]];
const now=Date.now(), seen=new Set(), articles=[], health=[];
const clean=s=>String(s||'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
const relevant = /\b(fed|ecb|central bank|interest rates?|inflation|monetary|economy|economic|gdp|employment|payrolls?|unemployment|treasur(?:y|ies)|bond yields?|dollar|euro|currency|forex|gold|silver|bullion|bitcoin|btc|crypto|stablecoins?|oil|energy|tariffs?|sanctions?|trade|banking|financial|markets?)\b/i;
const usable=s=>s.length>=80 && s.split(/\s+/).length>=10 && !/^read more\b/i.test(s) && !/^https?:\/\//i.test(s);
for(const [name,category] of sources){
 let data=[]; try{data=$(name).all().map(x=>x.json);}catch(e){}
 const valid=data.filter(x=>x.title && (x.link||x.guid));
 let accepted=0, rejected=0, duplicates=0, capped=0, insufficient_content=0, off_topic=0;
 for(const j of valid.sort((a,b)=>Date.parse(b.isoDate||b.pubDate)-Date.parse(a.isoDate||a.pubDate))){
  const t=Date.parse(j.isoDate||j.pubDate||'');
  if(!Number.isFinite(t)||t<now-cfg.lookbackHours*3600000||t>now+300000){rejected++;continue;}
  let url=String(j.link||j.guid).trim().split('#')[0];
  // Reject non-http links; remove tracking parameters without requiring Node URL globals.
  if(!/^https?:\/\/[^\s/@]+(?:\/|$)/i.test(url)){rejected++;continue;}
  const [base,qs]=url.split('?');
  const keep=(qs||'').split('&').filter(x=>x&&!/^(utm_[^=]*|fbclid|gclid)=/i.test(x));
  url=base+(keep.length?'?'+keep.join('&'):'');
  const title=clean(j.title).slice(0,400);
  const excerpts=[j.contentSnippet,j.description,j.content,j['content:encoded'],j['content:encodedSnippet']].map(clean).filter(usable).sort((a,b)=>b.length-a.length);
  if(!excerpts.length){insufficient_content++;rejected++;continue;}
  const description=excerpts[0].slice(0,1800);
  if(category==='geopolitics' && !relevant.test(title+' '+description)){off_topic++;rejected++;continue;}
  if(seen.has(url)){duplicates++;continue;}
  if(accepted>=cfg.maxPerSource){capped++;continue;}
  seen.add(url);accepted++;
  articles.push({url,title,description,published_at:new Date(t).toISOString(),source:name,category});
 }
 const error=data.find(x=>x.error);
 health.push({source:name,status:error?'error':valid.length?'ok':'empty',received:valid.length,accepted,rejected,duplicates,capped,insufficient_content,off_topic});
}
return [{json:{articles,health,healthy:health.filter(x=>x.status==='ok').length,execution_id:String($execution.id)}}];

const a=$('Build AI Request').item.json,c=$('Config').first().json,r=$input.first().json;
let result=null,status='failed',error=null,text='';
try {
 if(r.error) throw new Error('AI request failed; inspect node execution');
const raw = r.text ?? r.output;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('AI returned no text');
}

const cleaned = raw.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '');

result = JSON.parse(cleaned);

if (!result || typeof result !== 'object' || Array.isArray(result)) {
  throw new Error('AI response must be a JSON object');
}
 if(!Number.isInteger(result.score)||result.score<1||result.score>5)throw new Error('Invalid score');
 if(typeof result.confidence!=='number'||!Number.isFinite(result.confidence)||result.confidence<0||result.confidence>1)throw new Error('Invalid confidence');
 if(typeof result.needs_review!=='boolean')throw new Error('Invalid review flag');
 for(const [k,max] of [['title_fa',200],['summary_fa',700],['why_fa',350]]){
  if(typeof result[k]!=='string'||!result[k].trim()||result[k].length>max)throw new Error('Invalid '+k);
 }
 if(!/[\u0600-\u06ff]/.test(result.summary_fa))throw new Error('Summary is not Persian');
 if(!Array.isArray(result.impacts)||result.impacts.length>5)throw new Error('Invalid impacts');
 const assets=new Set();
 for(const x of result.impacts){
  if(!['XAU','XAG','BTC','USD','EUR'].includes(x.asset)||assets.has(x.asset)||!['bullish','bearish','mixed','neutral','unclear'].includes(x.direction)||typeof x.reason_fa!=='string'||!x.reason_fa.trim()||x.reason_fa.length>180)throw new Error('Invalid asset impact');
  assets.add(x.asset);
 }
 // Evidence presence is a guard, not proof of the model's reasoning.
 const normalize=s=>String(s||'').replace(/\s+/g,' ').trim();
 const sourceText=normalize(a.title+' '+a.description);
 const qualityIssues=[];
 for(const x of result.impacts){
  const q=normalize(x.evidence_quote);
  if(q.length<20||q.length>300||!sourceText.includes(q))qualityIssues.push('Missing or unmatched evidence: '+x.asset);
 }
 // Conservative numeric check. It does not verify units or meaning.
 const digits=s=>String(s).replace(/[۰-۹]/g,ch=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(ch))).replace(/[٠-٩]/g,ch=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(ch))).replace(/٬/g,',').replace(/٫/g,'.');
 const nums=s=>(digits(s).match(/\d+(?:,\d{3})*(?:\.\d+)?/g)||[]).map(x=>String(Number(x.replace(/,/g,''))));
 const available=new Set(nums(a.title+' '+a.description));
 const prose=[result.title_fa,result.summary_fa,result.why_fa,...result.impacts.map(x=>x.reason_fa)].join(' ');
 if(nums(prose).some(x=>!available.has(x)))qualityIssues.push('Number absent from supplied RSS text');
 result.quality_issues=qualityIssues;
 if(qualityIssues.length)result.needs_review=true;
 const dir={bullish:'احتمال اثر مثبت',bearish:'احتمال اثر منفی',mixed:'اثر دوگانه',neutral:'خنثی',unclear:'نامشخص'};
 const parts = [
  result.title_fa,
  result.summary_fa,
  `چرا مهم است؟\n${result.why_fa}`
];

if (result.impacts.length) {
  parts.push(
    'برداشت احتمالی بازار:\n' +
    result.impacts.map(x =>
      `${x.asset}: ${dir[x.direction]} — ${x.reason_fa}`
    ).join('\n')
  );
}

const published = new Date(a.published_at);
const displayDate = Number.isNaN(published.getTime())
  ? String(a.published_at)
  : new Intl.DateTimeFormat('fa-IR', {
      timeZone: 'Asia/Tehran',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(published);

parts.push(
  `منبع: ${a.source}\n${displayDate}، به وقت تهران\n${a.url}`
);

text = parts.join('\n\n');
 if(text.length>3900)throw new Error('Message exceeds safe length');
 status=result.score<c.minScore?'filtered':result.needs_review||result.confidence<c.minConfidence?'review':c.dryRun?'preview':!c.autoPublish?'review':'ready';
}catch(e){error=e.message;status='failed';}
return [{json:{id:a.id,status,result,text,error,model:r.model||c.model,usage:r.usage||{},prompt_version:c.promptVersion,owner:String($execution.id)}}];

const a=$('Reserve Delivery').item.json,r=$input.first().json;
const mid=r.result?.message_id ?? r.message_id;
const confirmed=!r.error && r.ok!==false && Number.isInteger(Number(mid)) && Number(mid)>0;
return [{json:{id:a.id,status:confirmed?'sent':'send_unknown',message_id:confirmed?String(mid):null,error:confirmed?null:'Delivery not confirmed. Inspect Telegram and execution before any resend.',owner:String($execution.id)}}];

const items=$input.all().map(x=>x.json).filter(x=>x.id!==undefined&&x.id!==null);
const health=$('Normalize and Feed Health').first().json.health;
const counts={};for(const x of items)counts[x.status||'unknown']=(counts[x.status||'unknown']||0)+1;
const failed=items.filter(x=>['failed','send_unknown'].includes(x.status));
if(failed.length)throw new Error('Analysis/delivery needs attention. IDs: '+failed.map(x=>x.id).join(', ')+'. Inspect database; do not blindly resend.');
const bad=health.filter(x=>x.status==='error');
const warnings=bad.map(x=>'Feed unavailable: '+x.source);
return [{json:{execution_id:String($execution.id),dryRun:$('Config').first().json.dryRun,processed:items.length,counts,warnings,feedHealth:health}}];
